sent, subs = [], {}  # 종목 → 보고 있는 탭 집합

def subscribe(tab, code):
    s = subs.setdefault(code, set())
    if not s:
        sent.append(f"SUB {code}")
    s.add(tab)

def unsubscribe(tab, code):
    s = subs.get(code)
    if s is None:
        return
    s.discard(tab)
    if not s:
        sent.append(f"UNSUB {code}")
        del subs[code]

def close_tab(tab):
    for code in list(subs):
        unsubscribe(tab, code)

subscribe("tab1", "005930"); subscribe("tab2", "005930"); subscribe("tab3", "005930")
subscribe("tab2", "AAPL")
close_tab("tab1"); close_tab("tab2")
print(" | ".join(sent))
print({c: len(s) for c, s in subs.items()})
